      return prepareHighSchoolYearTwoEvaluationMatch();
    }
    return getCurrentEventId() === "high_school_followup_evaluation"
      ? prepareHighSchoolFollowupEvaluationMatch()
      : prepareHighSchoolYearOneMatch();
